#!/usr/bin/env python3
import re

# 读取原文件
with open\('kline_au888.html', 'r', encoding='utf-8'\) as f:
    content = f.read\(\)

# 定义 VWAP 指标的开始和结束标记
vwap_start = "        // 注册VWAP自定义指标（多周期：5, 10, 40, 60）"
vwap_end = "        }\);\\n\\n        // 浅色主题配置"

# 找到 VWAP 部分并替换
zigzag_code = """        // 注册ZIGZAG自定义指标（之字转向指标）
        klinecharts.registerIndicator\({
            name: 'ZIGZAG',
            shortName: 'ZIGZAG',
            precision: 4,
            calcParams: [5],  // 最小价格变化百分比（阈值）
            shouldOhlc: true,
            figures: [
                { key: 'zigzag', title: 'ZIGZAG: ', type: 'line' }
            ],
            calc: \(dataList, { calcParams }\) => {
                const results = [];
                const threshold = calcParams[0] / 100; // 转换为百分比

                let pivotHigh = null;
                let pivotLow = null;
                let lastPivot = null;
                let trend = null; // 'up' or 'down'

                dataList.forEach\(\(kLineData, i\) => {
                    const result = {};
                    const high = kLineData.high;
                    const low = kLineData.low;

                    // 初始化
                    if \(i === 0\) {
                        pivotHigh = high;
                        pivotLow = low;
                        lastPivot = { type: 'low', value: low, index: 0 };
                        result.zigzag = low;
                    } else {
                        // 检测新的峰谷
                        if \(high > pivotHigh\) {
                            pivotHigh = high;
                        }
                        if \(low < pivotLow\) {
                            pivotLow = low;
                        }

                        // 根据当前趋势判断转向
                        if \(trend === null\) {
                            // 初始趋势未定，等待突破
                            const change = \(pivotHigh - pivotLow\) / pivotLow;
                            if \(change >= threshold\) {
                                trend = 'up';
                                lastPivot = { type: 'low', value: pivotLow, index: i };
                                result.zigzag = pivotLow;
                            } else if \(change <= -threshold\) {
                                trend = 'down';
                                lastPivot = { type: 'high', value: pivotHigh, index: i };
                                result.zigzag = pivotHigh;
                            }
                        } else if \(trend === 'up'\) {
                            // 上升趋势，寻找峰值
                            const changeFromLow = \(high - lastPivot.value\) / lastPivot.value;
                            const changeFromHigh = \(pivotHigh - high\) / high;

                            if \(changeFromLow >= threshold\) {
                                // 可能的峰值
                                if \(changeFromHigh >= threshold\) {
                                    // 确认转向，更新峰谷
                                    trend = 'down';
                                    lastPivot = { type: 'high', value: pivotHigh, index: i };
                                    result.zigzag = pivotHigh;
                                    pivotLow = low;
                                }
                            } else {
                                result.zigzag = lastPivot.value;
                            }
                        } else if \(trend === 'down'\) {
                            // 下降趋势，寻找谷底
                            const changeFromHigh = \(lastPivot.value - low\) / lastPivot.value;
                            const changeFromLow = \(low - pivotLow\) / pivotLow;

                            if \(changeFromHigh >= threshold\) {
                                // 可能的谷底
                                if \(changeFromLow >= threshold\) {
                                    // 确认转向，更新峰谷
                                    trend = 'up';
                                    lastPivot = { type: 'low', value: pivotLow, index: i };
                                    result.zigzag = pivotLow;
                                    pivotHigh = high;
                                }
                            } else {
                                result.zigzag = lastPivot.value;
                            }
                        }

                        // 如果没有新值，延续上一个转折点
                        if \(!result.zigzag && lastPivot\) {
                            result.zigzag = lastPivot.value;
                        }
                    }

                    results.push\(result\);
                }\);

                return results;
            }
        }\);

        // 浅色主题配置"""

# 使用正则表达式替换
pattern = r'        // 注册VWAP自定义指标.*?        \\}\\\);.*?        // 浅色主题配置'
replacement = zigzag_code

new_content = re.sub\(pattern, replacement, content, flags=re.DOTALL\)

# 替换 createIndicator 中的 VWAP 为 ZIGZAG
new_content = new_content.replace\("chart.createIndicator\('VWAP', true, { id: 'candle_pane' }\);", 
                                  "chart.createIndicator\('ZIGZAG', true, { id: 'candle_pane' }\);"\)

# 写入新文件
with open\('kline_au888.html', 'w', encoding='utf-8'\) as f:
    f.write\(new_content\)

print\("✅ 成功将 VWAP 指标替换为 ZIGZAG 指标"\)
PYEOF)
